CREATE DATABASE IF NOT EXISTS customer_churn_analytics;
USE customer_churn_analytics;
SET FOREIGN_KEY_CHECKS=0;
DROP TABLE IF EXISTS marketing_campaigns,churn_history,customer_feedback,support_tickets,service_usage,transactions,subscriptions,customers;
CREATE TABLE customers (customer_id VARCHAR(30) PRIMARY KEY, first_name VARCHAR(50), last_name VARCHAR(50), gender VARCHAR(20), date_of_birth DATE, age INT, city VARCHAR(50), state VARCHAR(50), region VARCHAR(30), postal_code INT, customer_segment VARCHAR(30), acquisition_channel VARCHAR(30), acquisition_date DATETIME, referral_source VARCHAR(30), marital_status VARCHAR(20), employment_status VARCHAR(30), annual_income DECIMAL(12,2), family_size INT, customer_status VARCHAR(20), created_date DATETIME, churn_flag TINYINT);
CREATE TABLE subscriptions (subscription_id VARCHAR(30) PRIMARY KEY, customer_id VARCHAR(30), plan_id VARCHAR(30), plan_name VARCHAR(50), subscription_type VARCHAR(30), contract_type VARCHAR(30), start_date DATETIME, end_date DATETIME, renewal_date DATETIME, auto_renewal VARCHAR(10), monthly_fee DECIMAL(10,2), discount_percentage DECIMAL(6,2), add_on_count INT, payment_method VARCHAR(30), subscription_status VARCHAR(30), cancellation_date DATETIME, cancellation_reason VARCHAR(60), churn_flag TINYINT, FOREIGN KEY(customer_id) REFERENCES customers(customer_id));
CREATE TABLE transactions (transaction_id VARCHAR(30) PRIMARY KEY, subscription_id VARCHAR(30), transaction_date DATETIME, transaction_type VARCHAR(30), invoice_id VARCHAR(30), payment_method VARCHAR(30), amount DECIMAL(12,2), discount DECIMAL(12,2), tax DECIMAL(12,2), net_amount DECIMAL(12,2), payment_status VARCHAR(30), payment_delay_days INT, refund_flag VARCHAR(10), refund_amount DECIMAL(12,2), failed_payment_count INT, currency CHAR(3), FOREIGN KEY(subscription_id) REFERENCES subscriptions(subscription_id));
CREATE TABLE service_usage (usage_id VARCHAR(30) PRIMARY KEY, customer_id VARCHAR(30), usage_month VARCHAR(20), login_count INT, session_count INT, avg_session_minutes DECIMAL(10,2), data_usage_gb DECIMAL(12,2), feature_usage_count INT, active_days INT, inactive_days INT, service_usage_level VARCHAR(30), last_login_date DATETIME, days_since_last_login INT, churn_flag TINYINT, FOREIGN KEY(customer_id) REFERENCES customers(customer_id));
CREATE TABLE support_tickets (ticket_id VARCHAR(30) PRIMARY KEY, customer_id VARCHAR(30), ticket_date DATETIME, ticket_category VARCHAR(40), issue_type VARCHAR(40), priority VARCHAR(20), channel VARCHAR(20), resolution_time_hours DECIMAL(10,2), first_response_time_hours DECIMAL(10,2), resolution_status VARCHAR(30), escalated VARCHAR(10), reopen_count INT, customer_satisfaction DECIMAL(5,2), agent_id VARCHAR(30), root_cause VARCHAR(40), FOREIGN KEY(customer_id) REFERENCES customers(customer_id));
CREATE TABLE customer_feedback (feedback_id VARCHAR(30) PRIMARY KEY, customer_id VARCHAR(30), feedback_date DATETIME, rating INT, nps_score INT, satisfaction_score INT, product_quality_score INT, service_score INT, price_value_score INT, ease_of_use_score INT, feedback_category VARCHAR(40), feedback_text VARCHAR(255), sentiment VARCHAR(20), satisfaction_group VARCHAR(30), churn_flag TINYINT, FOREIGN KEY(customer_id) REFERENCES customers(customer_id));
CREATE TABLE churn_history (churn_id VARCHAR(30) PRIMARY KEY, customer_id VARCHAR(30), subscription_id VARCHAR(30), churn_date DATETIME, churn_flag TINYINT, churn_type VARCHAR(30), churn_reason VARCHAR(60), churn_category VARCHAR(40), tenure_months INT, final_monthly_fee DECIMAL(10,2), outstanding_amount DECIMAL(12,2), competitor_joined VARCHAR(10), exit_feedback VARCHAR(255), winback_eligible VARCHAR(10), winback_status VARCHAR(30), tenure_month_group VARCHAR(30), FOREIGN KEY(customer_id) REFERENCES customers(customer_id), FOREIGN KEY(subscription_id) REFERENCES subscriptions(subscription_id));
CREATE TABLE marketing_campaigns (campaign_id VARCHAR(30) PRIMARY KEY, customer_id VARCHAR(30), campaign_date DATETIME, campaign_type VARCHAR(40), channel VARCHAR(20), offer_type VARCHAR(40), offer_value DECIMAL(10,2), sent_flag TINYINT, opened_flag TINYINT, clicked_flag TINYINT, redeemed_flag TINYINT, response_status VARCHAR(30), campaign_cost DECIMAL(12,2), revenue_generated DECIMAL(12,2), FOREIGN KEY(customer_id) REFERENCES customers(customer_id));
SET FOREIGN_KEY_CHECKS=1;






















SELECT 'customers' table_name,COUNT(*) row_count FROM customers UNION ALL SELECT 'subscriptions',COUNT(*) FROM subscriptions UNION ALL SELECT 'transactions',COUNT(*) FROM transactions UNION ALL SELECT 'service_usage',COUNT(*) FROM service_usage UNION ALL SELECT 'support_tickets',COUNT(*) FROM support_tickets UNION ALL SELECT 'customer_feedback',COUNT(*) FROM customer_feedback UNION ALL SELECT 'churn_history',COUNT(*) FROM churn_history UNION ALL SELECT 'marketing_campaigns',COUNT(*) FROM marketing_campaigns;
SELECT COUNT(*) AS invalid_churn_links FROM churn_history ch LEFT JOIN customers c ON ch.customer_id=c.customer_id LEFT JOIN subscriptions s ON ch.subscription_id=s.subscription_id WHERE c.customer_id IS NULL OR s.subscription_id IS NULL;